INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Ejyke90/kudegowo/openspec-sync-specs', 'community', 'Ejyke90', 'kudegowo', 'Ejyke90/kudegowo', 'openspec-sync-specs', 0, 0, 45, '2026-02-18T01:08:43.504Z', '2026-02-18T11:53:35.943Z', NULL, '{"id":"Ejyke90/kudegowo/openspec-sync-specs","name":"openspec-sync-specs","description":{"zh":"openspec-sync-specs 是一种智能规格合并工具，能够同步 delta 规格到主规格","ja":"openspec-sync-specs はスマートなスペックのマージツールで、delta スペックをメインスペックに同期できます","ko":"openspec-sync-specs는智能 규격 병합 도구로 delta 규격을 주 규격에 동기화 할 수 있습니다","es":"openspec-sync-specs es una operación de agente que sincroniza delta specs con main specs de manera inteligente, permitiendo la fusión de cambios sin copiar requisitos completos.","fr":"openspec-sync-specs est une opération d''agent qui synchronise les delta specs avec les main specs de manière intelligente, permettant la fusion de modifications sans copier les exigences complètes.","de":"openspec-sync-specs ist eine Agenten-Operation, die Delta-Specs mit Main-Specs intelligent synchronisiert, wodurch die Zusammenführung von Änderungen ohne Kopieren vollständiger Anforderungen ermöglicht wird.","pt":"O openspec-sync-specs é uma operação de agente que sincroniza delta specs com main specs, permitindo a mesclagem inteligente de cenários.","ru":"Openspec-sync-specs - это операция агента, которая синхронизирует delta specs с main specs, позволяя выполнять умные операции слияния сценариев.","ar":"openspec-sync-specs هو عملية وسيطة التي متوافق مواصفات دلتا مع مواصفات رئيسية، مما يسمح بدمج الذكية السيناريوهات.","en":""},"seo":{"title":{"zh":"openspec-sync-specs 同步规格","ja":"openspec-sync-specs スペック同期","ko":"openspec-sync-specs 규격 동기화","es":"Sincronización de especificaciones con openspec-sync-specs","fr":"Synchroniser les spécifications avec openspec-sync-specs","de":"Spezifikationen mit openspec-sync-specs synchronisieren","pt":"Sincronize